<?php
include_once 'includes/session_check.php';
require_login_modal();
include 'db_connect.php';
$school=(int)($_SESSION['login_school_id']??0);if($school<=0)die('Institución no válida.');
function pprBind(mysqli_stmt $stmt,string $types,array &$params):void{if($types==='')return;$args=[$types];foreach($params as &$value)$args[]=&$value;call_user_func_array([$stmt,'bind_param'],$args);}
$startDate=trim($_GET['start_date']??'');$endDate=trim($_GET['end_date']??'');$year=(int)($_GET['academic_year_id']??0);$level=trim($_GET['nivel_educativo']??'');$grade=trim($_GET['grado']??'');$section=trim($_GET['seccion']??'');$student=(int)($_GET['student_id']??0);$method=(int)($_GET['payment_method_id']??0);$course=(int)($_GET['course_id']??0);$studentStatus=trim($_GET['student_status']??'');$status=trim($_GET['operation_status']??'Confirmado');
$schoolData=['name'=>'Institución Educativa','address'=>'','logo_path'=>''];$stmt=$conn->prepare('SELECT name,address,logo_path FROM schools WHERE id=? LIMIT 1');$stmt->bind_param('i',$school);$stmt->execute();$schoolData=array_merge($schoolData,$stmt->get_result()->fetch_assoc()?:[]);$stmt->close();
$snapshots=false;$q=$conn->query("SHOW TABLES LIKE 'payment_concept_snapshots'");if($q&&$q->num_rows)$snapshots=true;$discounts=false;$q=$conn->query("SHOW TABLES LIKE 'payment_discount_snapshots'");if($q&&$q->num_rows)$discounts=true;
$where=['po.school_id=?'];$types='i';$params=[$school];$add=function($sql,$type,$value)use(&$where,&$types,&$params){if($value===''||$value===0)return;$where[]=$sql;$types.=$type;$params[]=$value;};$add('DATE(po.payment_date)>=?','s',$startDate);$add('DATE(po.payment_date)<=?','s',$endDate);$add('s.nivel=?','s',$level);$add('s.grado=?','s',$grade);$add('s.seccion=?','s',$section);$add('s.id=?','i',$student);$add('s.status=?','s',$studentStatus);if(in_array($status,['Confirmado','Anulado'],true))$add('po.status=?','s',$status);if($method>0){$where[]='EXISTS(SELECT 1 FROM payment_operation_methods fm WHERE fm.operation_id=po.id AND fm.payment_method_id=?)';$types.='i';$params[]=$method;}if($year>0){$where[]='EXISTS(SELECT 1 FROM payments fp INNER JOIN student_ef_list fe ON fe.id=fp.ef_id INNER JOIN courses fc ON fc.id=fe.course_id WHERE fp.operation_id=po.id AND fc.academic_year_id=?)';$types.='i';$params[]=$year;}if($course>0){$where[]='EXISTS(SELECT 1 FROM payments fp INNER JOIN student_ef_list fe ON fe.id=fp.ef_id WHERE fp.operation_id=po.id AND fe.course_id=?)';$types.='i';$params[]=$course;}$whereSql=implode(' AND ',$where);
$legacy="(p.operation_id=po.id OR (p.operation_id IS NULL AND po.receipt_series='LEG' AND ef.student_id=po.student_id AND CONVERT(po.receipt_full USING utf8mb4) COLLATE utf8mb4_general_ci=CONVERT(CONCAT('LEG-',po.school_id,'-',po.student_id,'-',p.receipt_no) USING utf8mb4) COLLATE utf8mb4_general_ci))";$fallback="(SELECT GROUP_CONCAT(DISTINCT CONCAT(COALESCE(c.course,CONCAT('Concepto histórico #',ef.course_id)),IF(ay.year IS NOT NULL,CONCAT(' · ',ay.year),'')) ORDER BY p.id SEPARATOR ' | ') FROM payments p INNER JOIN student_ef_list ef ON ef.id=p.ef_id LEFT JOIN courses c ON c.id=ef.course_id LEFT JOIN academic_year ay ON ay.id=c.academic_year_id WHERE $legacy)";$conceptExpr=$snapshots?"COALESCE((SELECT GROUP_CONCAT(DISTINCT CONCAT(COALESCE(NULLIF(sc.concept_name,''),'Concepto histórico'),IF(COALESCE(sc.academic_year_label,'')<>'',CONCAT(' · ',sc.academic_year_label),'')) ORDER BY sc.id SEPARATOR ' | ') FROM payment_concept_snapshots sc WHERE sc.payment_operation_id=po.id),$fallback)":$fallback;$discountExpr=$discounts?'COALESCE((SELECT SUM(sd.discount_amount) FROM payment_discount_snapshots sd WHERE sd.payment_operation_id=po.id),0)':'0';$amountExpr=$method>0?'(SELECT COALESCE(SUM(sm.amount),0) FROM payment_operation_methods sm WHERE sm.operation_id=po.id AND sm.payment_method_id='.(int)$method.')':'po.total_amount';
$sql="SELECT po.receipt_full,po.payment_date,po.status,s.id_no,s.name student_name,s.nivel,s.grado,s.seccion,$conceptExpr concepts,$discountExpr discount_amount,$amountExpr reported_amount,(SELECT GROUP_CONCAT(CONCAT(COALESCE(pm.name,'No especificado'),': S/ ',FORMAT(pom.amount,2)) ORDER BY pom.id SEPARATOR ' | ') FROM payment_operation_methods pom LEFT JOIN payment_methods pm ON pm.id=pom.payment_method_id WHERE pom.operation_id=po.id) methods FROM payment_operations po INNER JOIN student s ON s.id=po.student_id WHERE $whereSql ORDER BY po.payment_date DESC,po.id DESC";$stmt=$conn->prepare($sql);if(!$stmt)die('No se pudo preparar el reporte: '.htmlspecialchars($conn->error));pprBind($stmt,$types,$params);$stmt->execute();$result=$stmt->get_result();$rows=[];$confirmed=0;$cancelled=0;$discountTotal=0;while($row=$result->fetch_assoc()){$rows[]=$row;if($row['status']==='Anulado')$cancelled+=(float)$row['reported_amount'];else$confirmed+=(float)$row['reported_amount'];$discountTotal+=(float)$row['discount_amount'];}$stmt->close();
$period=$startDate&&$endDate?'Del '.date('d/m/Y',strtotime($startDate)).' al '.date('d/m/Y',strtotime($endDate)):($startDate?'Desde '.date('d/m/Y',strtotime($startDate)):($endDate?'Hasta '.date('d/m/Y',strtotime($endDate)):'Todas las fechas'));
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Reporte de pagos</title><style>
@page{size:A4 landscape;margin:10mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#253858;font-size:10px;margin:0}.toolbar{display:flex;justify-content:flex-end;margin-bottom:10px}.toolbar button{padding:8px 14px;border:0;border-radius:5px;background:#2f6fed;color:#fff;cursor:pointer}.header{display:flex;align-items:center;border-bottom:2px solid #2f6fed;padding-bottom:9px;margin-bottom:10px}.logo{width:58px;height:58px;object-fit:contain;margin-right:12px}.header h1{font-size:18px;margin:0}.header p{margin:3px 0;color:#667085}.title{text-align:right;margin-left:auto}.title strong{display:block;font-size:17px}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:10px 0}.box{border:1px solid #dfe5ee;border-radius:6px;padding:8px}.box span{display:block;color:#667085}.box b{font-size:13px}table{width:100%;border-collapse:collapse}thead{display:table-header-group}tr{page-break-inside:avoid}th{background:#eef3fb;color:#344767;text-align:left;padding:6px;border:1px solid #d9e0ea}td{padding:5px 6px;border:1px solid #d9e0ea;vertical-align:top}.amount{text-align:right;white-space:nowrap}.cancelled{color:#b42318;font-weight:bold}.confirmed{color:#067647;font-weight:bold}.muted{color:#667085;font-size:9px}.footer{text-align:center;margin-top:8px;color:#98a2b3}@media print{.toolbar{display:none}}
</style></head><body><div class="toolbar"><button onclick="window.print()">Imprimir</button></div><div class="header"><?php if(!empty($schoolData['logo_path'])&&file_exists($schoolData['logo_path'])): ?><img class="logo" src="<?php echo htmlspecialchars($schoolData['logo_path']); ?>"><?php endif; ?><div><h1><?php echo htmlspecialchars($schoolData['name']); ?></h1><p><?php echo htmlspecialchars($schoolData['address']); ?></p></div><div class="title"><strong>Reporte de pagos</strong><span><?php echo htmlspecialchars($period); ?></span><div class="muted">Generado: <?php echo date('d/m/Y H:i'); ?></div></div></div><div class="summary"><div class="box"><span>Operaciones</span><b><?php echo number_format(count($rows)); ?></b></div><div class="box"><span>Total confirmado</span><b>S/ <?php echo number_format($confirmed,2); ?></b></div><div class="box"><span>Total anulado</span><b>S/ <?php echo number_format($cancelled,2); ?></b></div><div class="box"><span>Descuentos documentados</span><b>S/ <?php echo number_format($discountTotal,2); ?></b></div></div><table><thead><tr><th>Fecha</th><th>Recibo</th><th>Estudiante</th><th>Conceptos cubiertos</th><th>Medios de pago</th><th>Descuento</th><th>Total</th><th>Estado</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="8" style="text-align:center;padding:20px">No se encontraron operaciones con los filtros seleccionados.</td></tr><?php endif; ?><?php foreach($rows as $row): ?><tr><td><?php echo date('d/m/Y H:i',strtotime($row['payment_date'])); ?></td><td><b><?php echo htmlspecialchars($row['receipt_full']); ?></b></td><td><b><?php echo htmlspecialchars($row['student_name']); ?></b><div class="muted"><?php echo htmlspecialchars($row['id_no'].' · '.$row['nivel'].' · '.$row['grado'].' '.$row['seccion']); ?></div></td><td><?php echo htmlspecialchars($row['concepts']?:'Concepto no disponible'); ?></td><td><?php echo htmlspecialchars($row['methods']?:'No especificado'); ?></td><td class="amount">S/ <?php echo number_format((float)$row['discount_amount'],2); ?></td><td class="amount"><b>S/ <?php echo number_format((float)$row['reported_amount'],2); ?></b></td><td class="<?php echo $row['status']==='Confirmado'?'confirmed':'cancelled'; ?>"><?php echo htmlspecialchars($row['status']); ?></td></tr><?php endforeach; ?></tbody></table><div class="footer">Reporte interno de control financiero · <?php echo htmlspecialchars($schoolData['name']); ?></div></body></html>
